 "content": "def transform(grid):
    """Extend a repeated row pattern into its trailing background, marking
    only cells whose extrapolated value is the row's foreground with 1."""
    from collections import Counter
    if not grid:
        return []
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    fg = next((x for x, _ in counts.most_common() if x != bg), bg)
    out = [row[:] for row in grid]
    width = len(grid[0])
    for r, row in enumerate(grid):
        if len(row) != width or not row or row[-1] != bg:
            continue
        start = width
        while start > 0 and row[start - 1] == bg:
            start -= 1
        if start == 0:
            continue
        # Use the shortest period supported by two complete repetitions
        # immediately before the trailing background run.
        period = None
        for p in range(1, min(8, start // 2) + 1):
            sample = row[start - 2 * p:start]
            if all(sample[i] == sample[i % p] for i in range(2 * p)):
                period = p
                break
        if period is None:
            continue
        pattern = row[start - period:start]
        for c in range(start, width):
            if pattern[(c - start) % period] == fg:
                out[r][c] = 1
    return out

